<script>
let periodIndex=document.querySelectorAll('#period-list .schedule-row').length;
const slotOption=document.getElementById('slot-option');function updateSlotFields(){if(!slotOption)return;const online=slotOption.selectedOptions[0]?.dataset.type==='online';document.getElementById('meeting-url-field').hidden=!online;document.getElementById('clinic-location-field').hidden=online;document.getElementById('slot-meeting-url').required=online;document.getElementById('slot-clinic-location').required=!online;}slotOption?.addEventListener('change',updateSlotFields);updateSlotFields();
document.getElementById('add-period').addEventListener('click',()=>{const i=periodIndex++,row=document.createElement('fieldset');row.className='schedule-row';row.innerHTML='<legend>Working period '+(i+1)+'</legend><div class="form-row"><div><label>Weekday</label><select name="periods['+i+'][day_of_week]">'+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,n)=>'<option value="'+n+'">'+d+'</option>').join('')+'</select></div><div><label>Starts</label><input type="time" name="periods['+i+'][starts_at]" required></div><div><label>Ends</label><input type="time" name="periods['+i+'][ends_at]" required></div></div><p>Breaks (optional)</p><div class="break-list"></div><button type="button" class="btn btn-outline btn-small add-break" data-index="'+i+'">Add break</button>';document.getElementById('period-list').appendChild(row)});
document.addEventListener('click',e=>{if(!e.target.matches('.add-break'))return;const i=e.target.dataset.index,row=e.target.closest('.schedule-row'),j=row.querySelectorAll('.break-row').length,b=document.createElement('div');b.className='form-row break-row';b.innerHTML='<input name="periods['+i+'][breaks]['+j+'][label]" aria-label="Break name" placeholder="Lunch"><input type="time" name="periods['+i+'][breaks]['+j+'][starts_at]" aria-label="Break starts"><input type="time" name="periods['+i+'][breaks]['+j+'][ends_at]" aria-label="Break ends">';row.insertBefore(b,e.target)});
</script>
